output_text:
[
  {
    "id": "must_take_cart_at_entrance",
    "text": "Shoppers are obliged to pick up the entrance cart before doing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_rack": "at(1,5)",
        "cart_available_at_rack": "cartAt(1,5)"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_rack",
              "cart_available_at_rack",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Shoppers are prohibited from taking shelf items unless they are currently pushing or holding the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "return_cart_to_service_bay",
    "text": "After taking a cart, the shopper is obliged to return it at the customer-service cart bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "at_service_cart_bay": "at(0,1)",
        "cart_parked_at_service_bay": "cartAt(0,1)"
      },
      "events": {
        "pickup_any_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_service_bay": {
          "pre": {
            "and": [
              "at_service_cart_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_any_cart",
      "discharge": "return_cart_to_service_bay"
    }
  },
  {
    "id": "no_exit_with_unreturned_cart",
    "text": "The shopper is prohibited from exiting unless the cart has already been parked at the service bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cartAt(0,1)"
        },
        "at_store_exit": "at(9,5)"
      },
      "events": {
        "exit_without_returned_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_without_returned_cart"
    }
  },
  {
    "id": "cart_may_only_be_left_at_return_bay",
    "text": "A shopper may not put the cart down anywhere except the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_designated_return_bay": "at(0,1)",
        "away_from_designated_return_bay": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_designated_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_bay"
    }
  },
  {
    "id": "after_any_item_return_cart",
    "text": "After every item pickup, the shopper is obliged eventually to return the cart to the service bay before leaving.",
    "abstraction": {
      "state_properties": {
        "at_service_bay": "at(0,1)",
        "cart_at_service_bay": "cartAt(0,1)"
      },
      "events": {
        "item_collected": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cart_deposited_at_service_bay": {
          "pre": {
            "and": [
              "at_service_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_at_service_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_collected",
      "discharge": "cart_deposited_at_service_bay"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "The norm forbids carrying shopping items by hand rather than putting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "using_cart_for_storage": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {
        "pickup_causes_hand_carry": {
          "pre": "PICKUP_ITEM",
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart is returned at the service bay, the shopper is prohibited from further shopping interactions and should only proceed to the exit.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)",
        "not_exiting": {
          "not": "EXIT"
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT",
              "not_exiting"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
